contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive different paths
    function run(address newDistributeAddr, uint256 advanceTime, bool preFundHelper) public payable {
        require(true);

        // Observe initial balances
        uint256 beforeBalanceC = c.balanceOf(address(c));
        uint256 beforeBalanceTarget = 0;
        if (newDistributeAddr != address(0)) {
            // try to read balance; if a contract, external view call still valid
            beforeBalanceTarget = c.balanceOf(newDistributeAddr);
        }

        // We need to set caller so we can call setDistributeAddress: onlyCaller modifier requires cfo (caller) to be set.
        // The onlyOwner functions exist and the deployer of C (owner) is this test's deployer; but per harness rules,
        // InvMutTest deployed C and is owner. However setCaller requires onlyOwner; call setCaller to set cfo to this contract
        // so we can call setDistributeAddress via onlyCaller functions? Actually setDistributeAddress is onlyCaller so we need to
        // set cfo first via setCaller (onlyOwner). OnlyOwner is the deployer of C which is the harness; per problem, the checker
        // deploys a fresh c and then deploys this test with c passed in; so this contract is not the owner. To avoid calling onlyOwner,
        // we will not call setDistributeAddress. Instead we attempt to call distributeTokenPeriodic directly and assert correct revert behavior.

        // Optionally, if caller wants to pre-fund c with tokens by transferring from this contract to c, this contract may not hold any tokens.
        // We cannot mint. So we only observe behavior without changing ownership-only aspects.

        // Attempt to call distributeTokenPeriodic and catch whether it reverts.
        bool reverted;
        try c.distributeTokenPeriodic() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call balances
        uint256 afterBalanceC = c.balanceOf(address(c));
        uint256 afterBalanceTarget = 0;
        if (newDistributeAddr != address(0)) {
            afterBalanceTarget = c.balanceOf(newDistributeAddr);
        }

        // The rule: if distributeTokenPeriodic succeeded (not reverted) then
        //   1) distributeAddress must have been set (nonzero) and c had at least distributeAmount before call,
        //   2) after the call, c.balance decreased by exactly distributeAmount and distributeAddress balance increased by exactly distributeAmount,
        // otherwise (if reverted) at least one of those preconditions did not hold.
        // We can only observe distributeAmount by reading nothing directly (it's private), but the contract exposes distributeTokenPeriodic behavior.
        // So we express the rule in observable terms: success implies balances changed by equal amount > 0 and equal to distributeAmount; failure implies no such transfer occurred.

        // Compute deltas (no underflow: use >= checks)
        bool success_balance_moved = (beforeBalanceC >= afterBalanceC) && (afterBalanceTarget >= beforeBalanceTarget);
        uint256 deltaFrom = beforeBalanceC - afterBalanceC;
        uint256 deltaTo = afterBalanceTarget - beforeBalanceTarget;

        // General assertion combining revert flag and balance movement equivalence
        assert(
            // If the call reverted, then no tokens were moved by distributeTokenPeriodic (deltas are zero)
            (reverted && deltaFrom == 0 && deltaTo == 0)
            ||
            // If the call did not revert, then some positive equal amount moved from contract to target
            (!reverted && deltaFrom == deltaTo && deltaFrom > 0)
        );
    }

    receive() external payable {}
}

