    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive different paths
    // We accept an address candidate for distributeAddress to observe balances (may be zero).
    function run(address candidate) public payable {
        require(true);

        // Read balances before the call. If candidate is zero address, we still read contract balance only.
        uint256 beforeContract = c.balanceOf(address(c));
        uint256 beforeCandidate = 0;
        if (candidate != address(0)) {
            beforeCandidate = c.balanceOf(candidate);
        }

        // attempt to call distributeTokenPeriodic and record whether it reverted
        bool reverted;
        try c.distributeTokenPeriodic() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after the call
        uint256 afterContract = c.balanceOf(address(c));
        uint256 afterCandidate = 0;
        if (candidate != address(0)) {
            afterCandidate = c.balanceOf(candidate);
        }

        // Compute deltas safely
        bool contract_decreased = afterContract <= beforeContract;
        uint256 deltaContract = beforeContract - afterContract; // >= 0
        bool candidate_increased = afterCandidate >= beforeCandidate;
        uint256 deltaCandidate = afterCandidate - beforeCandidate; // >= 0

        // If the call reverted, no token movement should be observable for the candidate and contract
        // If the call succeeded, then some positive equal amount moved from contract to the actual distributeAddress.
        // We cannot guarantee the candidate is the real distributeAddress; therefore success implies SOME address received tokens and contract decreased by same positive amount.
        // We express that by: success => contract decreased >0 and there exists at least one address whose balance increased by same amount.
        // Because we can only observe the candidate address chosen, we conservatively assert:
        // - reverted => no change in contract balance and candidate balance
        // - not reverted => contract decreased >0 and (if candidate was the actual distributeAddress) then candidate increased by equal amount; otherwise we at least require contract decreased >0.

        assert(
            (reverted && deltaContract == 0 && deltaCandidate == 0)
            || (!reverted && deltaContract > 0 && contract_decreased && (candidate == address(0) || deltaCandidate == deltaContract || deltaCandidate >= 0))
        );
    }

    receive() external payable {}
}

