contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller will be this contract (msg.sender for c calls)
    // Parameters:
    // - token: the ERC20 token address to withdraw from the helper
    // - recipient: where withdrawn tokens should be sent
    // This test checks the invariant about withdrawHelperToken when invoked by the cfo (or not).
    function run(address token, address recipient) public payable {
        require(recipient != address(0)); // ensure we can observe recipient balance

        // Set this contract as owner-created cfo so onlyCaller functions can be called by us.
        // Only owner (which is the deployer of C) can setCaller. The InvMutTest deployed c, so msg.sender here is NOT owner.
        // Therefore we cannot call setCaller directly. Instead, attempt to call withdrawHelperToken and observe behavior.

        // Read balances before
        uint256 beforeHelper = IERC20(token).balanceOf(c.helperAddress());
        uint256 beforeRecipient = IERC20(token).balanceOf(recipient);

        // Try to call withdrawHelperToken; record whether it reverted
        bool reverted;
        try c.withdrawHelperToken(token, recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        uint256 afterHelper = IERC20(token).balanceOf(c.helperAddress());
        uint256 afterRecipient = IERC20(token).balanceOf(recipient);

        // If the call reverted, token balances must be unchanged for helper and recipient.
        // If it succeeded, then helper's balance must have decreased by exactly the increase of recipient and helper should be zero for that token if it sent its full balance.
        // The contract's withdrawToken implementation sends the full balance of the helper to _account and requires bal > 0.
        // Therefore success implies beforeHelper > 0 and afterHelper == 0 and afterRecipient == beforeRecipient + beforeHelper.

        assert(
            (reverted && afterHelper == beforeHelper && afterRecipient == beforeRecipient)
            || (!reverted && beforeHelper > 0 && afterHelper == 0 && afterRecipient == beforeRecipient + beforeHelper)
        );
    }

    // minimal interfaces used inside test to query balances and helperAddress
    interface IERC20 { function balanceOf(address) external view returns (uint256); }
 }

