contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256 advanceSeconds, address maybeDistributeAddr) public payable {
        require(advanceSeconds <= 1 days * 1000, "bound advance");
        // set up: make this contract the caller that can call onlyCaller functions by setting caller via owner
        // c was deployed fresh with owner = deployer (the deployer of C). InvMutTest is deployed after C,
        // so we cannot be owner. We will test distributeTokenPeriodic which is public (no onlyCaller) and uses initTime.

        // Ensure distributeAddress is set by attempting to set it through onlyOwner is impossible here, so we must
        // observe both behaviors: if distributeAddress is zero, call will revert. We cannot set owner or onlyCaller.

        // Read before values
        uint256 beforeInitTime = c.initTime();
        uint256 contractBalance = c.balanceOf(address(c));
        uint256 distributeAmount = c.distributeAmount();

        // Make sure the contract has enough balance to possibly succeed by minting tokens to it via transfer from owner
        // We cannot mint; but initial supply minted to C deployer (owner). However we can try transferring tokens from deployer only if allowed.
        // Instead, we avoid trying to change balances and write a property that covers both success and revert cases.

        // Advance block.timestamp by relying on advanceSeconds via a precondition: we require that block.timestamp + advanceSeconds > beforeInitTime
        // but we cannot change block.timestamp. So instead, we call distributeTokenPeriodic and capture whether it reverts.
        bool didRevert;
        uint256 afterInitTime;
        // attempt the call and catch revert
        try c.distributeTokenPeriodic() {
            didRevert = false;
            afterInitTime = c.initTime();
        } catch {
            didRevert = true;
            afterInitTime = c.initTime();
        }

        // The property: If the call succeeded (didRevert == false) then:
        //  - afterInitTime > beforeInitTime (initTime was advanced)
        //  - either distributeAddress was non-zero and contract had >= distributeAmount before the call
        //    and balanceOf(address(this contract)) decreased by exactly distributeAmount
        // We can only observe c.balanceOf(address(c)) before and after, so require that when call succeeded,
        // the contract's balance decreased by distributeAmount (or increased if tokens were minted elsewhere) would be violation.
        uint256 afterContractBalance = c.balanceOf(address(c));

        // Read distributeAddress (public? it's private in C, but there is no getter. So we cannot read distributeAddress.)
        // Instead we express property only in terms of observable initTime and balances.

        // Assert general rule
        // If call succeeded then initTime strictly increased and contract token balance decreased by at least distributeAmount
        // If call reverted then initTime did not increase (stays <= or equal). We avoid underflow by using comparisons.
        assert(
            (!didRevert && afterInitTime > beforeInitTime && beforeContractBalanceGreaterOrEqual(contractBalance, afterContractBalance, distributeAmount))
            || (didRevert && afterInitTime == beforeInitTime)
        );
    }

    // helper view used only inside this contract (not a separate function allowed by constraints?)
    // We implement an internal pure helper to compare without doing subtraction in the assert.
    function beforeContractBalanceGreaterOrEqual(uint256 beforeBal, uint256 afterBal, uint256 delta) internal pure returns (bool) {
        // returns true if beforeBal >= afterBal + delta  <=> beforeBal - afterBal >= delta
        if (beforeBal < afterBal) return false;
        uint256 diff = beforeBal - afterBal;
        return diff >= delta;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run() public payable {
        // Observe before-values via public surface
        uint256 beforePairBalance = c.balanceOf(c.pairAddress());
        uint256 beforeContractBalance = c.balanceOf(address(c));

        // We cannot access initTime (it's private), but there is a public function distributeTokenPeriodic() which updates it.
        // We'll call it and observe effects on contract token balance and pair balance (pair refund via burnPair calls _burn on pairAddress).

        bool didRevert;
        uint256 afterPairBalance;
        uint256 afterContractBalance;

        // Attempt the call and catch revert
        try c.distributeTokenPeriodic() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-values
        afterPairBalance = c.balanceOf(c.pairAddress());
        afterContractBalance = c.balanceOf(address(c));

        // Read distributeAmount observable (it is private in C, but there is a public getter 'distributeAmount' because it's declared without visibility? 
        // In the provided contract distributeAmount is not public. Cannot read it. Instead derive minimal transferred amount by checking that
        // if successful then contract balance decreased by at least 1 (nonzero) and pair balance did not increase beyond before (burn may reduce it).
        // To make a general rule we assert: if call reverted then balances unchanged; if succeeded then contract balance decreased (or equal if transferred from elsewhere)
        // and pair balance did not increase (burnPair only reduces and sync doesn't increase token balance).

        // Build the general rule as a single assert:
        // - If reverted: contract and pair balances are equal to before-values
        // - If succeeded: contract balance is <= beforeContractBalance and pair balance is <= beforePairBalance
        // This captures that successful distribution/burn cannot increase these observed balances.

        assert(
            (didRevert && afterContractBalance == beforeContractBalance && afterPairBalance == beforePairBalance)
            || (!didRevert && afterContractBalance <= beforeContractBalance && afterPairBalance <= beforePairBalance)
        );
    }

    receive() external payable {}
}

